import React, { Component } from 'react';
import Toolbar from '../../components/Navigation/Toolbar/Toolbar';
import './Layout.css';

class Layout extends Component {

    render () {
        return (
            <React.Fragment>
                <Toolbar/>
                <main className="Content">
                    {this.props.children}
                </main>
            </ React.Fragment>
        )
    }
}

export default Layout;
